/* eslint-disable react/destructuring-assignment */
import React, { FocusEvent, KeyboardEvent, InputHTMLAttributes, useState } from 'react';
import { Field } from 'react-final-form';
import classNames from 'classnames';
import LabeledInput from '../../../atoms/labeledInput';
// import InputStyleWrapper, { InputStyle } from '../../../atoms/inputStyleWrapper';
import NumberPicker from '../../../atoms/numberPicker';

import './index.less';

interface TimePickerProps extends InputHTMLAttributes<HTMLInputElement> {
  active?: boolean;
  label?: string;
  htmlFor: string;
  value?: string;
  hideLabel?: boolean;
  onClick?: React.MouseEventHandler<HTMLInputElement>;
}

const sanitizeNumber = (number: number) => (number < 10 ? `0${number}` : `${number}`);

const sanitizeTime = (hours: number, minutes: number) =>
  `${sanitizeNumber(hours)}:${sanitizeNumber(minutes)}`;

function TimePicker(labelProps: TimePickerProps) {
  const [timePickerVisible, setTimePickerVisibility] = useState(false);
  const labelValue = labelProps.value ? labelProps.value : undefined;
  const [initialHours, initialMinutes] = labelValue
    ?.split?.(':')
    ?.map?.((num) => Number.parseInt(num, 10)) ?? [undefined, undefined];
  const [hours, setHours] = useState<number | undefined>(initialHours);
  const [minutes, setMinutes] = useState<number | undefined>(initialMinutes);

  const setTime = (h: number | undefined, m: number | undefined) => {
    if (h !== undefined && m !== undefined) {
      labelProps.onChange?.(sanitizeTime(h, m) as any);
    }
  };

  const onPickerBlur = (event: FocusEvent<HTMLElement>) => {
    const { currentTarget } = event;

    setTimeout(() => {
      if (!currentTarget.contains(document.activeElement)) {
        setTimePickerVisibility(false);
        setTime(hours, minutes);
      }
    }, 0);
  };

  const onInputKeyPress = (event: KeyboardEvent<HTMLElement>) => {
    if (event.key === 'Enter') {
      setTimePickerVisibility(true);
      event.preventDefault();
    }
  };

  const onPickerKeyDown = (event: KeyboardEvent<HTMLElement>) => {
    if (event.key === 'Escape' && hours !== undefined && minutes !== undefined) {
      setTimePickerVisibility(false);
      event.preventDefault();
    }
  };

  const onHoursPicker = (number) => {
    setHours(number);
    setTime(number, minutes);

    if (minutes === undefined) {
      (document.getElementsByClassName('minutes-picker').item(0)
        ?.firstElementChild as HTMLElement)?.focus();
    }
  };

  const onMinutesPicker = (mins) => {
    setMinutes(mins);
    setTime(hours, mins);
  };

  return (
    <div onBlur={onPickerBlur} className={classNames('time-picker-input', labelProps.className)}>
      <LabeledInput
        type="text"
        onKeyPress={onInputKeyPress}
        placeholder={labelProps.label ? undefined : 'HH:MM'}
        readOnly
        {...labelProps}
        onClick={(event) => {
          setTimePickerVisibility(true);
          labelProps.onClick?.(event);
        }}
        label={labelProps.label}
      />
      <div className="time-picker-wrapper">
        <div className={classNames({ hide: !timePickerVisible }, 'time-picker')}>
          <NumberPicker
            start={0}
            end={23}
            value={hours}
            onNumberPicked={onHoursPicker}
            onKeyDown={onPickerKeyDown}
          />

          <NumberPicker
            className="minutes-picker"
            value={minutes}
            start={0}
            end={59}
            interval={5}
            leadingZero
            onNumberPicked={onMinutesPicker}
            onKeyDown={onPickerKeyDown}
          />
        </div>
      </div>
    </div>
  );
}

export interface TimePickerFieldProps {
  label?: string;
  name: string;
  className?: string;
  changeListener?: (time?: string) => void;
  onClick?: React.MouseEventHandler<HTMLInputElement>;
}

function TimePickerField({
  name,
  label,
  className,
  changeListener,
  onClick,
}: TimePickerFieldProps) {
  return (
    <Field
      name={name}
      render={({ meta, input }) => (
        <TimePicker
          className={className}
          label={label}
          active={meta.active || input.value}
          htmlFor={name}
          {...input}
          onClick={onClick}
          onChange={(event) => {
            changeListener?.((event as unknown) as string);
            input.onChange(event);
          }}
        />
      )}
    />
  );
}

export default TimePickerField;
